import hashlib
import hmac
import os
import time
import secrets
from functools import wraps
from flask import Flask, request, session, jsonify, abort
from PIL import Image
import io
import redis

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

redis_client = redis.Redis(host='localhost', port=6379, db=0)

CSRF_TOKEN_EXPIRY = 3600
MAX_IMAGE_SIZE = 10 * 1024 * 1024

class TenantContext:
    def __init__(self, tenant_id, user_id):
        self.tenant_id = tenant_id
        self.user_id = user_id
        self.permissions = set()

    def load_permissions(self):
        perms = redis_client.smembers(f"tenant:{self.tenant_id}:user:{self.user_id}:perms")
        self.permissions = {p.decode() for p in perms}
        return self

    def can_process_images(self):
        return 'image:process' in self.permissions

    def can_delete_images(self):
        return 'image:delete' in self.permissions


def generate_csrf_token(user_id, tenant_id):
    timestamp = str(int(time.time()))
    nonce = secrets.token_hex(16)
    payload = f"{user_id}:{tenant_id}:{timestamp}:{nonce}"
    secret = app.secret_key
    signature = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    token = f"{payload}:{signature}"
    redis_client.setex(f"csrf:{token}", CSRF_TOKEN_EXPIRY, "valid")
    return token


def validate_csrf_token(token, user_id, tenant_id):
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return False
    payload, provided_sig = parts
    payload_parts = payload.split(':')
    if len(payload_parts) != 4:
        return False
    token_user, token_tenant, timestamp, nonce = payload_parts
    if token_user != user_id or token_tenant != tenant_id:
        return False
    age = int(time.time()) - int(timestamp)
    if age > CSRF_TOKEN_EXPIRY or age < 0:
        return False
    secret = app.secret_key
    expected_sig = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_sig, provided_sig):
        return False
    cache_key = f"csrf:{token}"
    if not redis_client.exists(cache_key):
        return False
    return True


def require_csrf(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.method in ('GET', 'HEAD', 'OPTIONS'):
            return f(*args, **kwargs)
        user_id = session.get('user_id')
        tenant_id = session.get('tenant_id')
        if not user_id or not tenant_id:
            abort(401)
        csrf_token = request.headers.get('X-CSRF-Token', '')
        origin = request.headers.get('Origin', '')
        referer = request.headers.get('Referer', '')
        allowed_origins = redis_client.smembers(f"tenant:{tenant_id}:allowed_origins")
        allowed_origins = {o.decode() for o in allowed_origins}
        origin_valid = origin in allowed_origins if origin else True
        referer_valid = any(referer.startswith(o) for o in allowed_origins) if referer else True
        if origin_valid and referer_valid:
            if csrf_token and validate_csrf_token(csrf_token, user_id, tenant_id):
                return f(*args, **kwargs)
            elif not origin and not referer:
                return f(*args, **kwargs)
        abort(403)
    return decorated


def isolate_tenant(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        tenant_id = session.get('tenant_id')
        user_id = session.get('user_id')
        if not tenant_id or not user_id:
            abort(401)
        ctx = TenantContext(tenant_id, user_id).load_permissions()
        kwargs['tenant_ctx'] = ctx
        return f(*args, **kwargs)
    return decorated


@app.route('/api/images/process', methods=['POST'])
@require_csrf
@isolate_tenant
def process_image(tenant_ctx):
    if not tenant_ctx.can_process_images():
        abort(403)
    if 'image' not in request.files:
        return jsonify({'error': 'No image provided'}), 400
    image_file = request.files['image']
    if image_file.content_length and image_file.content_length > MAX_IMAGE_SIZE:
        return jsonify({'error': 'Image too large'}), 413
    operation = request.form.get('operation', 'thumbnail')
    allowed_ops = {'thumbnail', 'grayscale', 'rotate90', 'flip'}
    if operation not in allowed_ops:
        return jsonify({'error': 'Invalid operation'}), 400
    try:
        img_data = image_file.read()
        if len(img_data) > MAX_IMAGE_SIZE:
            return jsonify({'error': 'Image too large'}), 413
        img = Image.open(io.BytesIO(img_data))
        if operation == 'thumbnail':
            img.thumbnail((256, 256))
        elif operation == 'grayscale':
            img = img.convert('L')
        elif operation == 'rotate90':
            img = img.rotate(90)
        elif operation == 'flip':
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
        output = io.BytesIO()
        img.save(output, format='PNG')
        output.seek(0)
        image_id = secrets.token_hex(16)
        storage_key = f"tenant:{tenant_ctx.tenant_id}:images:{image_id}"
        redis_client.setex(storage_key, 86400, output.getvalue())
        return jsonify({'image_id': image_id, 'status': 'processed'})
    except Exception as e:
        return jsonify({'error': 'Processing failed'}), 500


@app.route('/api/images/<image_id>', methods=['DELETE'])
@require_csrf
@isolate_tenant
def delete_image(image_id, tenant_ctx):
    if not tenant_ctx.can_delete_images():
        abort(403)
    storage_key = f"tenant:{tenant_ctx.tenant_id}:images:{image_id}"
    if not redis_client.exists(storage_key):
        return jsonify({'error': 'Image not found'}), 404
    redis_client.delete(storage_key)
    return jsonify({'status': 'deleted'})


@app.route('/api/csrf-token', methods=['GET'])
def get_csrf_token():
    user_id = session.get('user_id')
    tenant_id = session.get('tenant_id')
    if not user_id or not tenant_id:
        abort(401)
    token = generate_csrf_token(user_id, tenant_id)
    return jsonify({'csrf_token': token})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
